codeExample.code:
# Conditional Statements in Python - Complete Example

# Get the student's marks as input
marks = int(input("Enter your marks (0-100): "))

# Check which grade the student gets
if marks >= 90:
    grade = "O (Outstanding)"
elif marks >= 75:
    grade = "A (Excellent)"
elif marks >= 60:
    grade = "B (Good)"
elif marks >= 40:
    grade = "C (Pass)"
else:
    grade = "F (Fail)"

# Print the result
print("Your grade is:", grade)

# Extra decision using logical operators
if marks >= 40 and marks <= 100:
    print("You are eligible for the next semester.")
else:
    print("Please appear for the supplementary exam.")

